import type { Phrase } from "./index";

export const help: Phrase[] = [
  ["our contact page", "notre page de contact", "unsere Kontaktseite", "nuestra página de contacto"],
  ["Delivery costs are shown in your basket and at checkout before you pay.", "Les frais de livraison s’affichent dans votre panier et à la caisse avant le paiement.", "Die Versandkosten werden vor der Zahlung in Ihrem Warenkorb und an der Kasse angezeigt.", "Los gastos de envío se muestran en tu cesta y al pagar, antes de abonar."],
  ["Orders of {money} or more qualify for free delivery.", "Les commandes de {money} ou plus bénéficient de la livraison gratuite.", "Bei Bestellungen ab {money} ist die Lieferung kostenlos.", "Los pedidos de {money} o más tienen envío gratuito."],
  ["We also offer {list}.", "Nous proposons aussi {list}.", "Außerdem bieten wir {list} an.", "También ofrecemos {list}."],
  ["Where is my order?", "Où est ma commande ?", "Wo ist meine Bestellung?", "¿Dónde está mi pedido?"],
  ["How to follow your order from payment to your door.", "Comment suivre votre commande, du paiement jusqu’à votre porte.", "So verfolgen Sie Ihre Bestellung von der Zahlung bis zu Ihrer Haustür.", "Cómo seguir tu pedido desde el pago hasta tu puerta."],
  ["Once you have paid, we email you an order confirmation. When your order ships we email you again, with tracking details where the carrier provides them.", "Une fois le paiement effectué, nous vous envoyons une confirmation de commande par e-mail. Lorsque votre commande est expédiée, nous vous écrivons à nouveau, avec les informations de suivi lorsque le transporteur en fournit.", "Sobald Sie bezahlt haben, senden wir Ihnen eine Bestellbestätigung per E-Mail. Wenn Ihre Bestellung versandt wird, schreiben wir Ihnen erneut, mit Sendungsverfolgung, sofern der Zusteller sie bereitstellt.", "Cuando hayas pagado, te enviamos por correo una confirmación del pedido. Cuando se envíe, te escribimos de nuevo, con los datos de seguimiento si el transportista los proporciona."],
  ["Many {name} products are printed to order, so they are made after you buy. Allow a few working days for printing, then the delivery time. Items in one order can be made in different places and arrive in separate parcels, each with its own tracking.", "Beaucoup de produits {name} sont imprimés à la commande : ils sont donc fabriqués après votre achat. Prévoyez quelques jours ouvrés pour l’impression, puis le délai de livraison. Les articles d’une même commande peuvent être fabriqués à différents endroits et arriver dans des colis séparés, chacun avec son propre suivi.", "Viele {name}-Produkte werden auf Bestellung gedruckt und erst nach Ihrem Kauf hergestellt. Rechnen Sie mit einigen Werktagen für den Druck, danach kommt die Lieferzeit. Artikel einer Bestellung können an verschiedenen Orten gefertigt werden und in getrennten Paketen ankommen, jedes mit eigener Sendungsverfolgung.", "Muchos productos de {name} se imprimen bajo pedido, así que se fabrican después de tu compra. Cuenta con unos días laborables para la impresión y luego el plazo de entrega. Los artículos de un mismo pedido pueden fabricarse en lugares distintos y llegar en paquetes separados, cada uno con su propio seguimiento."],
  ["To check on your order", "Pour vérifier votre commande", "So prüfen Sie Ihre Bestellung", "Para consultar tu pedido"],
  ["[Sign in to your account](/account) with the email you used at checkout.", "[Connectez-vous à votre compte](/account) avec l’e-mail utilisé lors de la commande.", "[Melden Sie sich in Ihrem Konto an](/account), mit der E-Mail-Adresse, die Sie an der Kasse verwendet haben.", "[Inicia sesión en tu cuenta](/account) con el correo que usaste al comprar."],
  ["Open your order to see its progress and any tracking link.", "Ouvrez votre commande pour voir son avancement et un éventuel lien de suivi.", "Öffnen Sie Ihre Bestellung, um den Fortschritt und einen möglichen Tracking-Link zu sehen.", "Abre tu pedido para ver su progreso y el enlace de seguimiento, si lo hay."],
  ["No account? Use the link in your shipping email.", "Pas de compte ? Utilisez le lien dans votre e-mail d’expédition.", "Kein Konto? Nutzen Sie den Link in Ihrer Versand-E-Mail.", "¿Sin cuenta? Usa el enlace del correo de envío."],
  ["If it has been longer than the delivery time we quoted, email us at {mail} with your order number and we will chase it.", "Si le délai de livraison annoncé est dépassé, écrivez-nous à {mail} en indiquant votre numéro de commande et nous ferons le suivi.", "Wenn die angegebene Lieferzeit überschritten ist, schreiben Sie uns an {mail} mit Ihrer Bestellnummer, und wir gehen der Sache nach.", "Si ha pasado más tiempo del plazo de entrega indicado, escríbenos a {mail} con tu número de pedido y lo investigaremos."],
  ["Why did my order come in separate parcels?", "Pourquoi ma commande est-elle arrivée en plusieurs colis ?", "Warum kam meine Bestellung in mehreren Paketen?", "¿Por qué mi pedido llegó en varios paquetes?"],
  ["Different items can be made and sent from different places.", "Les articles peuvent être fabriqués et expédiés depuis différents endroits.", "Artikel können an verschiedenen Orten gefertigt und versandt werden.", "Los artículos pueden fabricarse y enviarse desde lugares distintos."],
  ["Products printed to order can be produced by different print partners, so the items in one order may ship separately and arrive on different days.", "Les produits imprimés à la commande peuvent être fabriqués par différents partenaires d’impression : les articles d’une même commande peuvent donc être expédiés séparément et arriver à des jours différents.", "Auf Bestellung gedruckte Produkte können von verschiedenen Druckpartnern gefertigt werden, daher können die Artikel einer Bestellung getrennt versandt werden und an verschiedenen Tagen eintreffen.", "Los productos impresos bajo pedido pueden producirlos distintos socios de impresión, así que los artículos de un pedido pueden enviarse por separado y llegar en días diferentes."],
  ["You pay delivery once for the order as shown at checkout. Each parcel has its own tracking link in your shipping emails. If one parcel has not arrived after the others, check its tracking first, then contact us.", "Vous ne payez la livraison qu’une fois pour la commande, comme indiqué à la caisse. Chaque colis a son propre lien de suivi dans vos e-mails d’expédition. Si un colis n’est pas arrivé alors que les autres l’ont fait, vérifiez d’abord son suivi, puis contactez-nous.", "Die Lieferung zahlen Sie nur einmal pro Bestellung, wie an der Kasse angezeigt. Jedes Paket hat in Ihren Versand-E-Mails einen eigenen Tracking-Link. Wenn ein Paket nach den anderen nicht angekommen ist, prüfen Sie zuerst seine Sendungsverfolgung und kontaktieren Sie uns dann.", "Pagas el envío una sola vez por pedido, como se muestra al comprar. Cada paquete tiene su propio enlace de seguimiento en tus correos de envío. Si un paquete no ha llegado cuando los demás sí, revisa primero su seguimiento y luego contáctanos."],
  ["How do I cancel my order?", "Comment annuler ma commande ?", "Wie storniere ich meine Bestellung?", "¿Cómo cancelo mi pedido?"],
  ["What to do if you want to cancel, and what happens once printing has started.", "Que faire si vous souhaitez annuler, et ce qui se passe une fois l’impression commencée.", "Was Sie tun können, wenn Sie stornieren möchten, und was passiert, sobald der Druck begonnen hat.", "Qué hacer si quieres cancelar y qué pasa cuando la impresión ya ha empezado."],
  ["Email us at {mail} as soon as you can with your order number. If printing has not started we will cancel it and refund you to the payment method you used.", "Écrivez-nous à {mail} dès que possible en indiquant votre numéro de commande. Si l’impression n’a pas commencé, nous l’annulerons et vous rembourserons sur le moyen de paiement utilisé.", "Schreiben Sie uns so schnell wie möglich an {mail} mit Ihrer Bestellnummer. Wenn der Druck noch nicht begonnen hat, stornieren wir die Bestellung und erstatten Ihnen den Betrag auf die verwendete Zahlungsart.", "Escríbenos a {mail} lo antes posible con tu número de pedido. Si la impresión no ha empezado, lo cancelaremos y te reembolsaremos por el medio de pago que usaste."],
  ["Because products are made to order, we may not be able to stop an order once it is in production. If that happens, you can still use your legal right to cancel and return the goods (see [Returns and refunds](/help/returns/returns-policy)).", "Les produits étant fabriqués à la commande, il se peut que nous ne puissions plus arrêter une commande en production. Dans ce cas, vous pouvez toujours exercer votre droit légal de rétractation et renvoyer les articles (voir [Retours et remboursements](/help/returns/returns-policy)).", "Da Produkte auf Bestellung gefertigt werden, können wir eine Bestellung in der Produktion möglicherweise nicht mehr stoppen. In diesem Fall können Sie weiterhin Ihr gesetzliches Widerrufsrecht nutzen und die Ware zurücksenden (siehe [Rückgabe und Erstattung](/help/returns/returns-policy)).", "Como los productos se fabrican bajo pedido, puede que no podamos detener un pedido que ya está en producción. En ese caso, aún puedes ejercer tu derecho legal de desistimiento y devolver los artículos (consulta [Devoluciones y reembolsos](/help/returns/returns-policy))."],
  ["Why was my order cancelled?", "Pourquoi ma commande a-t-elle été annulée ?", "Warum wurde meine Bestellung storniert?", "¿Por qué se canceló mi pedido?"],
  ["The usual reasons an order is cancelled, and how refunds work.", "Les raisons habituelles d’une annulation et le fonctionnement des remboursements.", "Die üblichen Gründe für eine Stornierung und wie Erstattungen funktionieren.", "Los motivos habituales de una cancelación y cómo funcionan los reembolsos."],
  ["An order can be cancelled if your payment could not be completed or verified, if an item cannot be produced or is no longer available, or if we could not deliver to the address given.", "Une commande peut être annulée si votre paiement n’a pas pu être finalisé ou vérifié, si un article ne peut pas être produit ou n’est plus disponible, ou si nous n’avons pas pu livrer à l’adresse indiquée.", "Eine Bestellung kann storniert werden, wenn Ihre Zahlung nicht abgeschlossen oder verifiziert werden konnte, wenn ein Artikel nicht produziert werden kann oder nicht mehr verfügbar ist oder wenn wir an die angegebene Adresse nicht liefern konnten.", "Un pedido puede cancelarse si no se pudo completar o verificar tu pago, si un artículo no se puede producir o ya no está disponible, o si no pudimos entregar en la dirección indicada."],
  ["If we cancel, any payment taken is refunded to the original payment method. The time it takes to show up depends on your bank or card provider.", "En cas d’annulation de notre part, tout paiement encaissé est remboursé sur le moyen de paiement d’origine. Le délai d’apparition dépend de votre banque ou de votre émetteur de carte.", "Wenn wir stornieren, wird jede erhaltene Zahlung auf die ursprüngliche Zahlungsart erstattet. Wie lange es dauert, bis sie erscheint, hängt von Ihrer Bank oder Ihrem Kartenanbieter ab.", "Si cancelamos, cualquier pago recibido se reembolsa al medio de pago original. El tiempo que tarda en aparecer depende de tu banco o del emisor de tu tarjeta."],
  ["If you did not expect the cancellation, email {mail} with your order number and we will explain.", "Si vous ne vous attendiez pas à cette annulation, écrivez à {mail} en indiquant votre numéro de commande et nous vous expliquerons.", "Wenn Sie die Stornierung nicht erwartet haben, schreiben Sie an {mail} mit Ihrer Bestellnummer, und wir erklären es Ihnen.", "Si no esperabas la cancelación, escribe a {mail} con tu número de pedido y te lo explicaremos."],
  ["Can I change my delivery address or details?", "Puis-je modifier mon adresse de livraison ou mes informations ?", "Kann ich meine Lieferadresse oder Angaben ändern?", "¿Puedo cambiar mi dirección de entrega o mis datos?"],
  ["How to fix a mistake in the address after you have ordered.", "Comment corriger une erreur d’adresse après avoir commandé.", "So korrigieren Sie nach der Bestellung einen Fehler in der Adresse.", "Cómo corregir un error en la dirección después de pedir."],
  ["Email {mail} straight away with your order number and the correct address. If your order has not gone into production we can update it. Once it has shipped the carrier may not be able to redirect it.", "Écrivez à {mail} immédiatement avec votre numéro de commande et la bonne adresse. Si votre commande n’est pas encore en production, nous pouvons la modifier. Une fois expédiée, le transporteur ne pourra peut-être plus la rediriger.", "Schreiben Sie sofort an {mail} mit Ihrer Bestellnummer und der richtigen Adresse. Wenn Ihre Bestellung noch nicht in die Produktion gegangen ist, können wir sie ändern. Sobald sie versandt wurde, kann der Zusteller sie möglicherweise nicht mehr umleiten.", "Escribe a {mail} de inmediato con tu número de pedido y la dirección correcta. Si tu pedido aún no ha entrado en producción, podemos actualizarlo. Una vez enviado, puede que el transportista no pueda redirigirlo."],
  ["Please check your address carefully at checkout, as parcels sent to a wrong address we were given are not covered by our returns promise.", "Vérifiez bien votre adresse lors de la commande : les colis envoyés à une mauvaise adresse que vous nous avez communiquée ne sont pas couverts par notre garantie de retour.", "Bitte prüfen Sie Ihre Adresse an der Kasse sorgfältig, denn Pakete, die an eine uns falsch angegebene Adresse gesendet wurden, sind von unserem Rückgabeversprechen nicht abgedeckt.", "Revisa bien tu dirección al pagar, ya que los paquetes enviados a una dirección incorrecta que nos hayas dado no están cubiertos por nuestra garantía de devolución."],
  ["How long will delivery take?", "Combien de temps prend la livraison ?", "Wie lange dauert die Lieferung?", "¿Cuánto tarda la entrega?"],
  ["Production and delivery times for made-to-order products.", "Délais de production et de livraison des produits fabriqués à la commande.", "Produktions- und Lieferzeiten für Produkte, die auf Bestellung gefertigt werden.", "Plazos de producción y entrega de los productos fabricados bajo pedido."],
  ["Most of our products are printed to order. Allow a few working days for printing before your order is posted, plus the delivery time of the service used.", "La plupart de nos produits sont imprimés à la commande. Prévoyez quelques jours ouvrés pour l’impression avant l’envoi de votre commande, plus le délai de livraison du service utilisé.", "Die meisten unserer Produkte werden auf Bestellung gedruckt. Rechnen Sie mit einigen Werktagen für den Druck, bevor Ihre Bestellung versandt wird, plus der Lieferzeit des gewählten Dienstes.", "La mayoría de nuestros productos se imprimen bajo pedido. Cuenta con unos días laborables de impresión antes de que se envíe tu pedido, más el plazo de entrega del servicio utilizado."],
  ["The delivery estimate shown in your basket is a guide, not a guarantee. We email you when your order ships. If something is out of stock or delayed we will let you know.", "L’estimation de livraison affichée dans votre panier est indicative et non garantie. Nous vous écrivons lorsque votre commande est expédiée. Si un article est en rupture de stock ou retardé, nous vous le ferons savoir.", "Die im Warenkorb angezeigte Lieferschätzung ist ein Richtwert, keine Garantie. Wir schreiben Ihnen, sobald Ihre Bestellung versandt wird. Wenn etwas nicht vorrätig oder verzögert ist, informieren wir Sie.", "La estimación de entrega que se muestra en tu cesta es orientativa, no una garantía. Te escribimos cuando se envía tu pedido. Si algo está agotado o se retrasa, te lo haremos saber."],
  ["How much does delivery cost?", "Combien coûte la livraison ?", "Was kostet die Lieferung?", "¿Cuánto cuesta el envío?"],
  ["Delivery prices and when delivery is free.", "Tarifs de livraison et conditions de gratuité.", "Versandpreise und wann die Lieferung kostenlos ist.", "Precios de envío y cuándo es gratuito."],
  ["The exact amount is always shown in your basket and at checkout before you pay. For the full terms see [Delivery and returns](/delivery-returns).", "Le montant exact est toujours affiché dans votre panier et à la caisse avant le paiement. Pour les conditions complètes, voir [Livraison et retours](/delivery-returns).", "Der genaue Betrag wird vor der Zahlung immer in Ihrem Warenkorb und an der Kasse angezeigt. Die vollständigen Bedingungen finden Sie unter [Lieferung und Rückgabe](/delivery-returns).", "El importe exacto se muestra siempre en tu cesta y al pagar, antes de abonar. Para las condiciones completas, consulta [Envíos y devoluciones](/delivery-returns)."],
  ["Do you ship to my country?", "Livrez-vous dans mon pays ?", "Liefern Sie in mein Land?", "¿Enviáis a mi país?"],
  ["The countries we currently deliver to.", "Les pays dans lesquels nous livrons actuellement.", "Die Länder, in die wir derzeit liefern.", "Los países a los que enviamos actualmente."],
  ["We currently deliver to: {list}.", "Nous livrons actuellement dans les pays suivants : {list}.", "Wir liefern derzeit in folgende Länder: {list}.", "Actualmente enviamos a: {list}."],
  ["The countries we deliver to are listed at checkout.", "Les pays dans lesquels nous livrons sont indiqués à la caisse.", "Die Länder, in die wir liefern, werden an der Kasse aufgeführt.", "Los países a los que enviamos aparecen al pagar."],
  ["Gift cards are sent by email and can be bought from anywhere.", "Les cartes cadeaux sont envoyées par e-mail et peuvent être achetées de n’importe où.", "Geschenkkarten werden per E-Mail verschickt und können von überall gekauft werden.", "Las tarjetas regalo se envían por correo y se pueden comprar desde cualquier lugar."],
  ["Orders sent outside the UK may be subject to import duties, taxes or customs fees charged by the destination country. These are not included in our prices and are the recipient's responsibility.", "Les commandes expédiées hors du Royaume-Uni peuvent être soumises à des droits de douane, taxes ou frais de dédouanement prélevés par le pays de destination. Ils ne sont pas inclus dans nos prix et sont à la charge du destinataire.", "Bei Bestellungen außerhalb des Vereinigten Königreichs können vom Zielland Einfuhrzölle, Steuern oder Zollgebühren erhoben werden. Diese sind in unseren Preisen nicht enthalten und gehen zulasten des Empfängers.", "Los pedidos enviados fuera del Reino Unido pueden estar sujetos a aranceles de importación, impuestos o tasas de aduana del país de destino. No están incluidos en nuestros precios y corren a cargo del destinatario."],
  ["Do you offer gift wrapping?", "Proposez-vous l’emballage cadeau ?", "Bieten Sie Geschenkverpackung an?", "¿Ofrecéis envoltorio de regalo?"],
  ["How to add gift wrapping and a message.", "Comment ajouter un emballage cadeau et un message.", "So fügen Sie Geschenkverpackung und eine Nachricht hinzu.", "Cómo añadir envoltorio de regalo y un mensaje."],
  ["Yes. Choose gift wrapping at checkout for {money} per order.", "Oui. Choisissez l’emballage cadeau à la caisse pour {money} par commande.", "Ja. Wählen Sie an der Kasse die Geschenkverpackung für {money} pro Bestellung.", "Sí. Elige el envoltorio de regalo al pagar por {money} por pedido."],
  ["Gift wrapping is offered at checkout when it is available for your order.", "L’emballage cadeau est proposé à la caisse lorsqu’il est disponible pour votre commande.", "Geschenkverpackung wird an der Kasse angeboten, wenn sie für Ihre Bestellung verfügbar ist.", "El envoltorio de regalo se ofrece al pagar cuando está disponible para tu pedido."],
  ["If you are sending something to someone else, enter their address as the delivery address at checkout.", "Si vous envoyez quelque chose à quelqu’un d’autre, saisissez son adresse comme adresse de livraison à la caisse.", "Wenn Sie etwas an jemand anderen senden, geben Sie dessen Adresse an der Kasse als Lieferadresse ein.", "Si envías algo a otra persona, introduce su dirección como dirección de entrega al pagar."],
  ["What is your returns policy?", "Quelle est votre politique de retour ?", "Wie lautet Ihre Rückgaberichtlinie?", "¿Cuál es vuestra política de devoluciones?"],
  ["You have 14 days after receiving your goods to change your mind.", "Vous disposez de 14 jours après réception pour changer d’avis.", "Sie haben nach Erhalt der Ware 14 Tage Zeit, es sich anders zu überlegen.", "Tienes 14 días desde que recibes la mercancía para cambiar de opinión."],
  ["If you are buying as a consumer, you can cancel your order and return the goods for any reason within 14 days of receiving them. Tell us clearly (an email is fine) at {mail}, then send the goods back within a further 14 days.", "Si vous achetez en tant que consommateur, vous pouvez annuler votre commande et retourner les articles pour n’importe quelle raison dans les 14 jours suivant leur réception. Informez-nous clairement (un e-mail suffit) à {mail}, puis renvoyez les articles dans les 14 jours suivants.", "Wenn Sie als Verbraucher kaufen, können Sie Ihre Bestellung innerhalb von 14 Tagen nach Erhalt der Ware ohne Angabe von Gründen widerrufen und die Ware zurücksenden. Teilen Sie uns dies eindeutig mit (eine E-Mail genügt) an {mail} und senden Sie die Ware innerhalb weiterer 14 Tage zurück.", "Si compras como consumidor, puedes cancelar tu pedido y devolver la mercancía por cualquier motivo en los 14 días siguientes a recibirla. Indícanoslo claramente (basta un correo) en {mail} y devuelve los artículos en los 14 días siguientes."],
  ["We refund the price of the goods, and the standard delivery charge, within 14 days of getting the goods back or of you showing proof of postage, to the payment method you used. You pay the cost of sending items back unless we tell you otherwise.", "Nous remboursons le prix des articles et les frais de livraison standard dans les 14 jours suivant la réception du retour ou la preuve d’expédition, sur le moyen de paiement utilisé. Les frais de renvoi sont à votre charge, sauf indication contraire de notre part.", "Wir erstatten den Preis der Ware und die Standardlieferkosten innerhalb von 14 Tagen nach Erhalt der Rücksendung oder nach Vorlage eines Versandnachweises auf die verwendete Zahlungsart. Die Kosten der Rücksendung tragen Sie, sofern wir nichts anderes mitteilen.", "Reembolsamos el precio de la mercancía y los gastos de envío estándar en los 14 días siguientes a recibir la devolución o a que nos muestres el comprobante de envío, por el medio de pago que usaste. Los gastos de devolución corren de tu cuenta, salvo que te indiquemos lo contrario."],
  ["Please return items unused and in their original packaging where possible. We may reduce a refund if goods come back damaged or used beyond what is needed to check them.", "Retournez si possible les articles non utilisés et dans leur emballage d’origine. Nous pouvons réduire un remboursement si les articles reviennent endommagés ou utilisés au-delà de ce qui est nécessaire pour les vérifier.", "Senden Sie die Artikel bitte möglichst unbenutzt und in der Originalverpackung zurück. Wir können eine Erstattung mindern, wenn die Ware beschädigt oder über das zur Prüfung Notwendige hinaus benutzt zurückkommt.", "Devuelve los artículos sin usar y en su embalaje original siempre que sea posible. Podemos reducir un reembolso si la mercancía vuelve dañada o usada más allá de lo necesario para comprobarla."],
  ["Read the full wording in [Delivery and returns](/delivery-returns).", "Lisez le texte complet dans [Livraison et retours](/delivery-returns).", "Den vollständigen Wortlaut finden Sie unter [Lieferung und Rückgabe](/delivery-returns).", "Lee el texto completo en [Envíos y devoluciones](/delivery-returns)."],
  ["How do I return or exchange something?", "Comment retourner ou échanger un article ?", "Wie sende ich etwas zurück oder tausche es um?", "¿Cómo devuelvo o cambio algo?"],
  ["Step by step: telling us, posting it back and getting your money.", "Pas à pas : nous prévenir, renvoyer le colis et récupérer votre argent.", "Schritt für Schritt: uns informieren, zurücksenden und Ihr Geld erhalten.", "Paso a paso: avisarnos, enviarlo de vuelta y recibir tu dinero."],
  ["[Sign in to your account](/account), open the order and choose to request a return, or email us your order number and which items you are returning.", "[Connectez-vous à votre compte](/account), ouvrez la commande et demandez un retour, ou envoyez-nous votre numéro de commande et les articles à retourner.", "[Melden Sie sich in Ihrem Konto an](/account), öffnen Sie die Bestellung und beantragen Sie eine Rücksendung, oder senden Sie uns Ihre Bestellnummer und die zurückzusendenden Artikel.", "[Inicia sesión en tu cuenta](/account), abre el pedido y solicita una devolución, o envíanos tu número de pedido y los artículos que devuelves."],
  ["We confirm your request and tell you where to send the items.", "Nous confirmons votre demande et vous indiquons où envoyer les articles.", "Wir bestätigen Ihre Anfrage und teilen Ihnen mit, wohin Sie die Artikel senden.", "Confirmamos tu solicitud y te decimos adónde enviar los artículos."],
  ["Post the items back to us within 14 days of telling us. Keep your proof of postage.", "Renvoyez-nous les articles dans les 14 jours suivant votre demande. Conservez votre preuve d’expédition.", "Senden Sie die Artikel innerhalb von 14 Tagen nach Ihrer Mitteilung an uns zurück. Bewahren Sie Ihren Versandnachweis auf.", "Envíanos los artículos en los 14 días siguientes a avisarnos. Guarda tu comprobante de envío."],
  ["When your return arrives and is checked, we refund you to the original payment method.", "Une fois votre retour arrivé et vérifié, nous vous remboursons sur le moyen de paiement d’origine.", "Sobald Ihre Rücksendung eingetroffen und geprüft ist, erstatten wir Ihnen den Betrag auf die ursprüngliche Zahlungsart.", "Cuando tu devolución llega y se comprueba, te reembolsamos por el medio de pago original."],
  ["We do not swap items directly. To exchange something, return the original for a refund and place a new order for the size or item you want, so it is made fresh for you.", "Nous n’échangeons pas les articles directement. Pour un échange, retournez l’original contre remboursement et passez une nouvelle commande pour la taille ou l’article souhaité, afin qu’il soit fabriqué spécialement pour vous.", "Wir tauschen Artikel nicht direkt um. Für einen Umtausch senden Sie das Original gegen Erstattung zurück und bestellen die gewünschte Größe oder den gewünschten Artikel neu, damit er frisch für Sie gefertigt wird.", "No cambiamos artículos directamente. Para un cambio, devuelve el original a cambio de un reembolso y haz un nuevo pedido con la talla o el artículo que quieras, para que se fabrique de nuevo para ti."],
  ["What cannot be returned?", "Qu’est-ce qui ne peut pas être retourné ?", "Was kann nicht zurückgegeben werden?", "¿Qué no se puede devolver?"],
  ["Gift cards, personalised items and sealed hygiene items.", "Cartes cadeaux, articles personnalisés et articles d’hygiène scellés.", "Geschenkkarten, personalisierte Artikel und versiegelte Hygieneartikel.", "Tarjetas regalo, artículos personalizados y artículos de higiene precintados."],
  ["Gift cards, once issued.", "Cartes cadeaux, une fois émises.", "Geschenkkarten, sobald sie ausgestellt sind.", "Tarjetas regalo, una vez emitidas."],
  ["Items made or personalised to your request.", "Articles fabriqués ou personnalisés selon votre demande.", "Nach Ihren Vorgaben gefertigte oder personalisierte Artikel.", "Artículos fabricados o personalizados según tu petición."],
  ["Sealed items that cannot be returned for health or hygiene reasons once the seal has been broken, such as make-up and skincare.", "Articles scellés qui ne peuvent pas être retournés pour des raisons de santé ou d’hygiène une fois le scellé brisé, comme le maquillage et les soins de la peau.", "Versiegelte Artikel, die aus gesundheitlichen oder hygienischen Gründen nach Öffnen des Siegels nicht zurückgegeben werden können, etwa Make-up und Hautpflege.", "Artículos precintados que no se pueden devolver por motivos de salud o higiene una vez roto el precinto, como maquillaje y cuidado de la piel."],
  ["These exceptions do not affect your rights if an item is faulty. See [Something is missing, faulty or not as described](/help/returns/something-is-missing-or-wrong).", "Ces exceptions n’affectent pas vos droits si un article est défectueux. Voir [Un article manque, est défectueux ou non conforme](/help/returns/something-is-missing-or-wrong).", "Diese Ausnahmen berühren Ihre Rechte nicht, wenn ein Artikel mangelhaft ist. Siehe [Etwas fehlt, ist mangelhaft oder entspricht nicht der Beschreibung](/help/returns/something-is-missing-or-wrong).", "Estas excepciones no afectan a tus derechos si un artículo es defectuoso. Consulta [Falta algo, es defectuoso o no es como se describía](/help/returns/something-is-missing-or-wrong)."],
  ["Something is missing, faulty or not as described", "Un article manque, est défectueux ou non conforme", "Etwas fehlt, ist mangelhaft oder entspricht nicht der Beschreibung", "Falta algo, es defectuoso o no es como se describía"],
  ["How to ask for a repair, replacement or refund.", "Comment demander une réparation, un remplacement ou un remboursement.", "So beantragen Sie eine Reparatur, einen Ersatz oder eine Erstattung.", "Cómo pedir una reparación, un reemplazo o un reembolso."],
  ["Email {mail} with your order number, what is wrong and, if you can, a photo. We will put it right with a replacement or a refund.", "Écrivez à {mail} avec votre numéro de commande, le problème constaté et, si possible, une photo. Nous réglerons le problème par un remplacement ou un remboursement.", "Schreiben Sie an {mail} mit Ihrer Bestellnummer, dem Problem und, wenn möglich, einem Foto. Wir lösen es mit einem Ersatz oder einer Erstattung.", "Escribe a {mail} con tu número de pedido, qué falla y, si puedes, una foto. Lo solucionaremos con un reemplazo o un reembolso."],
  ["You have legal rights under the Consumer Rights Act 2015 to a repair, replacement or refund for goods that are faulty, damaged or not as described. These rights are in addition to your 14 day cancellation right and are not affected by the exceptions listed above.", "Vous disposez de droits légaux en vertu du Consumer Rights Act 2015 pour obtenir une réparation, un remplacement ou un remboursement pour des articles défectueux, endommagés ou non conformes à leur description. Ces droits s’ajoutent à votre droit de rétractation de 14 jours et ne sont pas affectés par les exceptions listées ci-dessus.", "Nach dem Consumer Rights Act 2015 haben Sie gesetzliche Rechte auf Reparatur, Ersatz oder Erstattung bei mangelhafter, beschädigter oder nicht wie beschrieben gelieferter Ware. Diese Rechte bestehen zusätzlich zu Ihrem 14-tägigen Widerrufsrecht und werden von den oben genannten Ausnahmen nicht berührt.", "Tienes derechos legales según la Consumer Rights Act 2015 a una reparación, un reemplazo o un reembolso por mercancía defectuosa, dañada o que no es como se describía. Estos derechos se suman a tu derecho de desistimiento de 14 días y no se ven afectados por las excepciones indicadas arriba."],
  ["If an item in your order has not arrived, check the tracking for each parcel first (see [Why did my order come in separate parcels?](/help/orders/separate-parcels)), then contact us.", "Si un article de votre commande n’est pas arrivé, vérifiez d’abord le suivi de chaque colis (voir [Pourquoi ma commande est-elle arrivée en plusieurs colis ?](/help/orders/separate-parcels)), puis contactez-nous.", "Wenn ein Artikel Ihrer Bestellung nicht angekommen ist, prüfen Sie zuerst die Sendungsverfolgung jedes Pakets (siehe [Warum kam meine Bestellung in mehreren Paketen?](/help/orders/separate-parcels)) und kontaktieren Sie uns dann.", "Si un artículo de tu pedido no ha llegado, revisa primero el seguimiento de cada paquete (consulta [¿Por qué mi pedido llegó en varios paquetes?](/help/orders/separate-parcels)) y luego contáctanos."],
  ["When will I get my refund?", "Quand serai-je remboursé ?", "Wann erhalte ich meine Erstattung?", "¿Cuándo recibiré mi reembolso?"],
  ["How long refunds take and where the money goes.", "Combien de temps prennent les remboursements et où va l’argent.", "Wie lange Erstattungen dauern und wohin das Geld geht.", "Cuánto tardan los reembolsos y adónde va el dinero."],
  ["Once we have received and checked your return, or agreed a refund, we send it within 14 days to the payment method you used.", "Une fois votre retour reçu et vérifié, ou un remboursement convenu, nous l’envoyons dans les 14 jours sur le moyen de paiement utilisé.", "Sobald wir Ihre Rücksendung erhalten und geprüft oder eine Erstattung vereinbart haben, senden wir sie innerhalb von 14 Tagen auf die verwendete Zahlungsart.", "Cuando hayamos recibido y comprobado tu devolución, o acordado un reembolso, lo enviamos en un plazo de 14 días al medio de pago que usaste."],
  ["After we send it, your bank or card provider decides how long it takes to appear, which is usually a few working days.", "Une fois envoyé, c’est votre banque ou votre émetteur de carte qui décide du délai d’apparition, généralement quelques jours ouvrés.", "Nach dem Absenden entscheidet Ihre Bank oder Ihr Kartenanbieter, wie lange es dauert, bis der Betrag erscheint, in der Regel einige Werktage.", "Tras enviarlo, tu banco o el emisor de tu tarjeta decide cuánto tarda en aparecer, normalmente unos días laborables."],
  ["If it has been longer than that, email {mail} with your order number.", "Si cela dure plus longtemps, écrivez à {mail} avec votre numéro de commande.", "Wenn es länger dauert, schreiben Sie an {mail} mit Ihrer Bestellnummer.", "Si ha pasado más tiempo, escribe a {mail} con tu número de pedido."],
  ["What payment types can I use?", "Quels moyens de paiement puis-je utiliser ?", "Welche Zahlungsarten kann ich nutzen?", "¿Qué formas de pago puedo usar?"],
  ["Cards, Apple Pay, Google Pay, gift cards and more.", "Cartes, Apple Pay, Google Pay, cartes cadeaux et plus.", "Karten, Apple Pay, Google Pay, Geschenkkarten und mehr.", "Tarjetas, Apple Pay, Google Pay, tarjetas regalo y más."],
  ["You can pay by debit or credit card, Apple Pay or Google Pay where your device supports them, or with a {name} gift card. {pay}", "Vous pouvez payer par carte de débit ou de crédit, Apple Pay ou Google Pay lorsque votre appareil les prend en charge, ou avec une carte cadeau {name}. {pay}", "Sie können mit Debit- oder Kreditkarte, mit Apple Pay oder Google Pay (sofern Ihr Gerät sie unterstützt) oder mit einer {name}-Geschenkkarte bezahlen. {pay}", "Puedes pagar con tarjeta de débito o crédito, con Apple Pay o Google Pay si tu dispositivo los admite, o con una tarjeta regalo de {name}. {pay}"],
  ["Which options you see at checkout depends on your device, browser, location and account. See all of them on our [Payment options](/payment-options) page.", "Les options affichées à la caisse dépendent de votre appareil, de votre navigateur, de votre localisation et de votre compte. Retrouvez-les toutes sur notre page [Options de paiement](/payment-options).", "Welche Optionen Sie an der Kasse sehen, hängt von Ihrem Gerät, Browser, Standort und Konto ab. Alle finden Sie auf unserer Seite [Zahlungsoptionen](/payment-options).", "Las opciones que ves al pagar dependen de tu dispositivo, navegador, ubicación y cuenta. Consúltalas todas en nuestra página de [Opciones de pago](/payment-options)."],
  ["Is it safe to pay on your site?", "Est-il sûr de payer sur votre site ?", "Ist die Zahlung auf Ihrer Website sicher?", "¿Es seguro pagar en vuestra web?"],
  ["Payments are handled by Stripe, so we never see your card details.", "Les paiements sont gérés par Stripe : nous ne voyons jamais vos données de carte.", "Zahlungen werden von Stripe abgewickelt, daher sehen wir Ihre Kartendaten nie.", "Los pagos los gestiona Stripe, así que nunca vemos los datos de tu tarjeta."],
  ["All payments are taken securely by Stripe. You pay on Stripe's own checkout page, so your full card details never touch our servers.", "Tous les paiements sont traités en toute sécurité par Stripe. Vous payez sur la page de paiement de Stripe elle-même : vos données de carte complètes ne passent donc jamais par nos serveurs.", "Alle Zahlungen werden sicher von Stripe abgewickelt. Sie zahlen auf der eigenen Checkout-Seite von Stripe, sodass Ihre vollständigen Kartendaten nie unsere Server berühren.", "Todos los pagos los procesa Stripe de forma segura. Pagas en la propia página de pago de Stripe, así que los datos completos de tu tarjeta nunca pasan por nuestros servidores."],
  ["Your bank may ask you to confirm a payment with an extra step (such as a code or your banking app). That is a normal security check.", "Votre banque peut vous demander de confirmer un paiement par une étape supplémentaire (un code ou votre application bancaire). C’est un contrôle de sécurité normal.", "Ihre Bank kann Sie bitten, eine Zahlung in einem zusätzlichen Schritt zu bestätigen (etwa mit einem Code oder Ihrer Banking-App). Das ist eine normale Sicherheitsprüfung.", "Tu banco puede pedirte que confirmes un pago con un paso adicional (como un código o tu app bancaria). Es una comprobación de seguridad normal."],
  ["How will my charge look on my statement?", "Comment mon débit apparaîtra-t-il sur mon relevé ?", "Wie erscheint die Abbuchung auf meinem Kontoauszug?", "¿Cómo aparecerá el cargo en mi extracto?"],
  ["What to do if you do not recognise a payment.", "Que faire si vous ne reconnaissez pas un paiement.", "Was Sie tun können, wenn Sie eine Zahlung nicht erkennen.", "Qué hacer si no reconoces un pago."],
  ["Your bank statement should show our trading name, {name}, and your bank may add details of the payment processor. Banks word these differently.", "Votre relevé bancaire doit afficher notre nom commercial, {name}, et votre banque peut ajouter des informations sur le prestataire de paiement. Les banques les libellent différemment.", "Auf Ihrem Kontoauszug sollte unser Handelsname {name} erscheinen, und Ihre Bank kann Angaben zum Zahlungsdienstleister ergänzen. Banken formulieren dies unterschiedlich.", "Tu extracto bancario debería mostrar nuestro nombre comercial, {name}, y tu banco puede añadir datos del procesador de pagos. Cada banco lo redacta de forma distinta."],
  ["If you do not recognise a charge, email {mail} with the date and amount and we will match it to an order.", "Si vous ne reconnaissez pas un débit, écrivez à {mail} avec la date et le montant et nous le rapprocherons d’une commande.", "Wenn Sie eine Abbuchung nicht erkennen, schreiben Sie an {mail} mit Datum und Betrag, und wir ordnen sie einer Bestellung zu.", "Si no reconoces un cargo, escribe a {mail} con la fecha y el importe y lo asociaremos a un pedido."],
  ["How do I use a discount code?", "Comment utiliser un code promo ?", "Wie verwende ich einen Rabattcode?", "¿Cómo uso un código de descuento?"],
  ["Where to enter a code and why one might not work.", "Où saisir un code et pourquoi il peut ne pas fonctionner.", "Wo Sie einen Code eingeben und warum er möglicherweise nicht funktioniert.", "Dónde introducir un código y por qué puede no funcionar."],
  ["Enter your code in your basket or at checkout and the discount is taken off your total.", "Saisissez votre code dans votre panier ou à la caisse et la remise est déduite de votre total.", "Geben Sie Ihren Code in Ihrem Warenkorb oder an der Kasse ein, und der Rabatt wird von Ihrer Summe abgezogen.", "Introduce tu código en la cesta o al pagar y el descuento se resta de tu total."],
  ["A code may not work if it has expired, has reached its limit, needs a minimum spend, or does not apply to the items in your basket. The message shown when you apply it says which.", "Un code peut ne pas fonctionner s’il a expiré, a atteint sa limite, nécessite un achat minimum ou ne s’applique pas aux articles de votre panier. Le message affiché lorsque vous l’appliquez indique laquelle de ces raisons s’applique.", "Ein Code funktioniert möglicherweise nicht, wenn er abgelaufen ist, sein Limit erreicht hat, einen Mindestbestellwert voraussetzt oder nicht für die Artikel in Ihrem Warenkorb gilt. Die Meldung beim Einlösen nennt den Grund.", "Un código puede no funcionar si ha caducado, ha alcanzado su límite, requiere un gasto mínimo o no se aplica a los artículos de tu cesta. El mensaje que aparece al aplicarlo indica cuál es el motivo."],
  ["Gift cards are not discount codes: you enter a gift card code in the gift card box and its balance is taken off your order.", "Les cartes cadeaux ne sont pas des codes promo : vous saisissez le code d’une carte cadeau dans le champ prévu et son solde est déduit de votre commande.", "Geschenkkarten sind keine Rabattcodes: Sie geben einen Geschenkkarten-Code im Feld für Geschenkkarten ein, und sein Guthaben wird von Ihrer Bestellung abgezogen.", "Las tarjetas regalo no son códigos de descuento: introduces el código de la tarjeta regalo en su casilla y su saldo se resta de tu pedido."],
  ["How do I buy and send a gift card?", "Comment acheter et envoyer une carte cadeau ?", "Wie kaufe und verschicke ich eine Geschenkkarte?", "¿Cómo compro y envío una tarjeta regalo?"],
  ["Pick an amount and a design, add a message and we email it.", "Choisissez un montant et un design, ajoutez un message et nous l’envoyons par e-mail.", "Wählen Sie Betrag und Design, fügen Sie eine Nachricht hinzu, und wir senden sie per E-Mail.", "Elige un importe y un diseño, añade un mensaje y la enviamos por correo."],
  ["Gift cards are sent by email as a unique code. Go to [Send a gift card](/gift-cards/send), choose an amount and a design, write a message and enter who it is for. You can send it to them directly or to yourself to pass on.", "Les cartes cadeaux sont envoyées par e-mail sous forme de code unique. Rendez-vous sur [Envoyer une carte cadeau](/gift-cards/send), choisissez un montant et un design, écrivez un message et indiquez le destinataire. Vous pouvez l’envoyer directement à la personne ou à vous-même pour la lui transmettre.", "Geschenkkarten werden als einmaliger Code per E-Mail verschickt. Gehen Sie zu [Geschenkkarte senden](/gift-cards/send), wählen Sie Betrag und Design, schreiben Sie eine Nachricht und geben Sie den Empfänger an. Sie können sie direkt an die Person oder an sich selbst senden, um sie weiterzugeben.", "Las tarjetas regalo se envían por correo como un código único. Ve a [Enviar una tarjeta regalo](/gift-cards/send), elige un importe y un diseño, escribe un mensaje e indica para quién es. Puedes enviarla directamente a la persona o a ti mismo para entregársela."],
  ["Gift cards are not refundable for cash once issued. If something goes wrong with delivery, contact us and we will resend it.", "Les cartes cadeaux ne sont pas remboursables en espèces une fois émises. En cas de problème de livraison, contactez-nous et nous la renverrons.", "Geschenkkarten werden nach Ausstellung nicht in bar erstattet. Falls bei der Zustellung etwas schiefgeht, kontaktieren Sie uns, und wir senden sie erneut.", "Las tarjetas regalo no son reembolsables en efectivo una vez emitidas. Si algo falla en la entrega, contáctanos y la reenviaremos."],
  ["How do I spend a gift card?", "Comment utiliser une carte cadeau ?", "Wie löse ich eine Geschenkkarte ein?", "¿Cómo uso una tarjeta regalo?"],
  ["Enter the code at checkout.", "Saisissez le code à la caisse.", "Geben Sie den Code an der Kasse ein.", "Introduce el código al pagar."],
  ["Add what you want to your basket.", "Ajoutez ce que vous voulez à votre panier.", "Legen Sie in den Warenkorb, was Sie möchten.", "Añade lo que quieras a tu cesta."],
  ["In the basket or at checkout, enter the gift card code in the gift card box and apply it.", "Dans le panier ou à la caisse, saisissez le code de la carte cadeau dans le champ prévu et appliquez-le.", "Geben Sie im Warenkorb oder an der Kasse den Geschenkkarten-Code im entsprechenden Feld ein und wenden Sie ihn an.", "En la cesta o al pagar, introduce el código de la tarjeta regalo en su casilla y aplícalo."],
  ["The balance is taken off your order. Any balance left over stays on the card for next time.", "Le solde est déduit de votre commande. Le solde restant demeure sur la carte pour la prochaine fois.", "Das Guthaben wird von Ihrer Bestellung abgezogen. Ein Restguthaben bleibt für das nächste Mal auf der Karte.", "El saldo se resta de tu pedido. El saldo restante se queda en la tarjeta para la próxima vez."],
  ["If the card does not cover the whole order, you can pay the rest with another payment method.", "Si la carte ne couvre pas toute la commande, vous pouvez payer le reste avec un autre moyen de paiement.", "Falls die Karte nicht die gesamte Bestellung abdeckt, können Sie den Rest mit einer anderen Zahlungsart begleichen.", "Si la tarjeta no cubre todo el pedido, puedes pagar el resto con otro medio de pago."],
  ["How do I check my gift card balance?", "Comment vérifier le solde de ma carte cadeau ?", "Wie prüfe ich das Guthaben meiner Geschenkkarte?", "¿Cómo consulto el saldo de mi tarjeta regalo?"],
  ["Look up what is left on a card.", "Consultez ce qu’il reste sur une carte.", "Sehen Sie nach, was auf einer Karte übrig ist.", "Consulta lo que queda en una tarjeta."],
  ["Enter your code on the [gift card balance page](/gift-cards/balance) to see what is left and whether the card is still usable.", "Saisissez votre code sur la [page de solde des cartes cadeaux](/gift-cards/balance) pour voir ce qu’il reste et si la carte est encore utilisable.", "Geben Sie Ihren Code auf der [Guthabenseite für Geschenkkarten](/gift-cards/balance) ein, um zu sehen, was übrig ist und ob die Karte noch nutzbar ist.", "Introduce tu código en la [página de saldo de tarjetas regalo](/gift-cards/balance) para ver lo que queda y si la tarjeta aún se puede usar."],
  ["If a card says it cannot be used and you think that is a mistake, email {mail} with the code and the email it was sent to.", "Si une carte indique qu’elle ne peut pas être utilisée et que vous pensez qu’il s’agit d’une erreur, écrivez à {mail} avec le code et l’adresse e-mail à laquelle elle a été envoyée.", "Wenn eine Karte als nicht nutzbar angezeigt wird und Sie einen Fehler vermuten, schreiben Sie an {mail} mit dem Code und der E-Mail-Adresse, an die sie gesendet wurde.", "Si una tarjeta indica que no se puede usar y crees que es un error, escribe a {mail} con el código y el correo al que se envió."],
  ["What does printed to order mean?", "Que signifie « imprimé à la commande » ?", "Was bedeutet „auf Bestellung gedruckt“?", "¿Qué significa «impreso bajo pedido»?"],
  ["Why products are made after you buy, and what that means for you.", "Pourquoi les produits sont fabriqués après votre achat, et ce que cela implique pour vous.", "Warum Produkte erst nach Ihrem Kauf hergestellt werden und was das für Sie bedeutet.", "Por qué los productos se fabrican después de tu compra y qué significa para ti."],
  ["Many of our products are printed only once you order them. That means less waste and no unsold stock, and it is why production takes a few working days before your order ships.", "Beaucoup de nos produits ne sont imprimés qu’une fois commandés. Cela signifie moins de gaspillage et pas de stock invendu, et c’est pourquoi la production prend quelques jours ouvrés avant l’expédition.", "Viele unserer Produkte werden erst gedruckt, wenn Sie sie bestellen. Das bedeutet weniger Verschwendung und keinen unverkauften Bestand, und deshalb dauert die Produktion einige Werktage, bevor Ihre Bestellung versandt wird.", "Muchos de nuestros productos solo se imprimen cuando los pides. Eso significa menos desperdicio y nada de stock sin vender, y es la razón por la que la producción tarda unos días laborables antes de enviarse tu pedido."],
  ["Colours can look slightly different on screen than in print, and from one print run to the next. Product pages describe the item and what it is made from.", "Les couleurs peuvent paraître légèrement différentes à l’écran et à l’impression, et d’un tirage à l’autre. Les pages produit décrivent l’article et ses matériaux.", "Farben können auf dem Bildschirm etwas anders wirken als im Druck und von einer Druckcharge zur nächsten. Die Produktseiten beschreiben den Artikel und das Material.", "Los colores pueden verse ligeramente distintos en pantalla que en impresión, y de una tirada a otra. Las páginas de producto describen el artículo y de qué está hecho."],
  ["How do I choose my size?", "Comment choisir ma taille ?", "Wie wähle ich meine Größe?", "¿Cómo elijo mi talla?"],
  ["Where to find size guides and what to do if it does not fit.", "Où trouver les guides des tailles et que faire si ça ne va pas.", "Wo Sie Größentabellen finden und was zu tun ist, wenn es nicht passt.", "Dónde encontrar las guías de tallas y qué hacer si no te queda bien."],
  ["Clothing pages have a size guide with measurements. Measure a similar item you already own and compare it to the guide.", "Les pages vêtements comportent un guide des tailles avec les mesures. Mesurez un article similaire que vous possédez déjà et comparez-le au guide.", "Auf den Bekleidungsseiten finden Sie eine Größentabelle mit Maßen. Messen Sie ein ähnliches Kleidungsstück, das Sie bereits besitzen, und vergleichen Sie es mit der Tabelle.", "Las páginas de ropa incluyen una guía de tallas con medidas. Mide una prenda similar que ya tengas y compárala con la guía."],
  ["If it does not fit, you can return it within 14 days of receiving it and order the size you want. See [How do I return or exchange something?](/help/returns/how-to-return).", "Si la taille ne convient pas, vous pouvez le retourner dans les 14 jours suivant la réception et commander la taille souhaitée. Voir [Comment retourner ou échanger un article ?](/help/returns/how-to-return).", "Wenn es nicht passt, können Sie den Artikel innerhalb von 14 Tagen nach Erhalt zurücksenden und die gewünschte Größe bestellen. Siehe [Wie sende ich etwas zurück oder tausche es um?](/help/returns/how-to-return).", "Si no te queda bien, puedes devolverlo en los 14 días siguientes a recibirlo y pedir la talla que quieras. Consulta [¿Cómo devuelvo o cambio algo?](/help/returns/how-to-return)."],
  ["I have a question before I buy", "J’ai une question avant d’acheter", "Ich habe eine Frage vor dem Kauf", "Tengo una pregunta antes de comprar"],
  ["How to ask about an item you are thinking of buying.", "Comment poser une question sur un article que vous envisagez d’acheter.", "So stellen Sie eine Frage zu einem Artikel, den Sie kaufen möchten.", "Cómo preguntar por un artículo que estás pensando en comprar."],
  ["Check the product page first for its description, sizes and materials. If you still need an answer, email {mail} and tell us which product you mean.", "Consultez d’abord la page produit pour la description, les tailles et les matériaux. Si vous avez encore besoin d’une réponse, écrivez à {mail} en précisant le produit concerné.", "Schauen Sie zuerst auf die Produktseite mit Beschreibung, Größen und Materialien. Wenn Sie noch eine Antwort brauchen, schreiben Sie an {mail} und nennen Sie uns das Produkt.", "Mira primero la página del producto con su descripción, tallas y materiales. Si aún necesitas una respuesta, escribe a {mail} e indícanos de qué producto se trata."],
  ["If something is out of stock, product pages let you ask to be told when it is back.", "Si un article est en rupture de stock, les pages produit permettent de demander à être prévenu de son retour.", "Wenn ein Artikel nicht vorrätig ist, können Sie sich auf der Produktseite benachrichtigen lassen, sobald er wieder da ist.", "Si un artículo está agotado, las páginas de producto permiten pedir un aviso cuando vuelva."],
  ["How do I sign in or reset my password?", "Comment me connecter ou réinitialiser mon mot de passe ?", "Wie melde ich mich an oder setze mein Passwort zurück?", "¿Cómo inicio sesión o restablezco mi contraseña?"],
  ["Getting into your account, and what to do if you are locked out.", "Accéder à votre compte et que faire si vous êtes bloqué.", "So gelangen Sie in Ihr Konto und was Sie tun können, wenn Sie ausgesperrt sind.", "Cómo acceder a tu cuenta y qué hacer si te quedas bloqueado."],
  ["Go to [Sign in](/account/login). If you have forgotten your password, choose the reset option and we email you a link.", "Rendez-vous sur [Connexion](/account/login). Si vous avez oublié votre mot de passe, choisissez l’option de réinitialisation et nous vous envoyons un lien par e-mail.", "Gehen Sie zu [Anmelden](/account/login). Wenn Sie Ihr Passwort vergessen haben, wählen Sie die Option zum Zurücksetzen, und wir senden Ihnen einen Link per E-Mail.", "Ve a [Iniciar sesión](/account/login). Si has olvidado tu contraseña, elige la opción de restablecer y te enviamos un enlace por correo."],
  ["After several wrong attempts you are asked to wait before trying again. This protects your account. If you do not get the email, check your spam folder, then contact us.", "Après plusieurs tentatives infructueuses, il vous est demandé d’attendre avant de réessayer. Cela protège votre compte. Si vous ne recevez pas l’e-mail, vérifiez vos courriers indésirables, puis contactez-nous.", "Nach mehreren falschen Versuchen werden Sie gebeten, zu warten, bevor Sie es erneut versuchen. Das schützt Ihr Konto. Wenn Sie die E-Mail nicht erhalten, prüfen Sie Ihren Spam-Ordner und kontaktieren Sie uns dann.", "Tras varios intentos fallidos se te pide que esperes antes de volver a intentarlo. Esto protege tu cuenta. Si no te llega el correo, revisa la carpeta de spam y luego contáctanos."],
  ["How does my wishlist work?", "Comment fonctionne ma liste de souhaits ?", "Wie funktioniert meine Wunschliste?", "¿Cómo funciona mi lista de deseos?"],
  ["Saving items for later.", "Enregistrer des articles pour plus tard.", "Artikel für später speichern.", "Guardar artículos para más tarde."],
  ["Tap the heart on any product to save it to your wishlist. Open your wishlist from the heart in the header to see everything you saved.", "Touchez le cœur sur n’importe quel produit pour l’ajouter à votre liste de souhaits. Ouvrez-la depuis le cœur dans l’en-tête pour voir tout ce que vous avez enregistré.", "Tippen Sie bei einem Produkt auf das Herz, um es auf Ihre Wunschliste zu setzen. Öffnen Sie Ihre Wunschliste über das Herz in der Kopfzeile, um alles Gespeicherte zu sehen.", "Toca el corazón de cualquier producto para guardarlo en tu lista de deseos. Abre tu lista desde el corazón de la cabecera para ver todo lo que guardaste."],
  ["Without an account, your wishlist is kept on the device you used. Clearing your browser data removes it.", "Sans compte, votre liste de souhaits est conservée sur l’appareil utilisé. Effacer les données de votre navigateur la supprime.", "Ohne Konto wird Ihre Wunschliste auf dem verwendeten Gerät gespeichert. Wenn Sie Ihre Browserdaten löschen, wird sie entfernt.", "Sin cuenta, tu lista de deseos se guarda en el dispositivo que usaste. Borrar los datos del navegador la elimina."],
  ["Accessibility", "Accessibilité", "Barrierefreiheit", "Accesibilidad"],
  ["How we make the shop usable for everyone, and how to tell us about a problem.", "Comment nous rendons la boutique utilisable par tous, et comment nous signaler un problème.", "Wie wir den Shop für alle nutzbar machen und wie Sie uns ein Problem melden.", "Cómo hacemos la tienda utilizable para todos y cómo avisarnos de un problema."],
  ["We want everyone to be able to shop here. Read our [accessibility statement](/accessibility) for how we do that and what we are still working on.", "Nous voulons que chacun puisse acheter ici. Lisez notre [déclaration d’accessibilité](/accessibility) pour savoir comment nous y travaillons et ce qu’il reste à améliorer.", "Wir möchten, dass jeder hier einkaufen kann. Lesen Sie unsere [Erklärung zur Barrierefreiheit](/accessibility), um zu erfahren, wie wir das umsetzen und woran wir noch arbeiten.", "Queremos que todo el mundo pueda comprar aquí. Lee nuestra [declaración de accesibilidad](/accessibility) para saber cómo lo hacemos y en qué seguimos trabajando."],
  ["If you find something hard to use, or need help placing an order, email {mail} and tell us what happened. We will help.", "Si vous trouvez quelque chose difficile à utiliser, ou si vous avez besoin d’aide pour passer commande, écrivez à {mail} en nous disant ce qui s’est passé. Nous vous aiderons.", "Wenn Ihnen etwas schwer zu bedienen erscheint oder Sie Hilfe bei der Bestellung brauchen, schreiben Sie an {mail} und schildern Sie, was passiert ist. Wir helfen Ihnen.", "Si algo te resulta difícil de usar o necesitas ayuda para hacer un pedido, escribe a {mail} y cuéntanos qué pasó. Te ayudaremos."],
  ["How do you use my personal data?", "Comment utilisez-vous mes données personnelles ?", "Wie verwenden Sie meine personenbezogenen Daten?", "¿Cómo usáis mis datos personales?"],
  ["What we collect, why, and your choices.", "Ce que nous collectons, pourquoi, et vos choix.", "Was wir erheben, warum und welche Wahlmöglichkeiten Sie haben.", "Qué recopilamos, por qué y qué opciones tienes."],
  ["Our [privacy policy](/privacy) explains what we collect, why, who we share it with and your rights, including asking us to see or delete your data. Our [cookie policy](/cookies) explains cookies, and you can change your choices at any time from the link in the footer.", "Notre [politique de confidentialité](/privacy) explique ce que nous collectons, pourquoi, avec qui nous le partageons et vos droits, notamment celui de demander à voir ou à supprimer vos données. Notre [politique de cookies](/cookies) explique les cookies, et vous pouvez modifier vos choix à tout moment depuis le lien en bas de page.", "Unsere [Datenschutzerklärung](/privacy) erklärt, was wir erheben, warum, an wen wir es weitergeben und welche Rechte Sie haben, einschließlich des Rechts, Einsicht in Ihre Daten oder deren Löschung zu verlangen. Unsere [Cookie-Richtlinie](/cookies) erklärt Cookies, und Sie können Ihre Auswahl jederzeit über den Link in der Fußzeile ändern.", "Nuestra [política de privacidad](/privacy) explica qué recopilamos, por qué, con quién lo compartimos y tus derechos, incluido el de pedir ver o borrar tus datos. Nuestra [política de cookies](/cookies) explica las cookies, y puedes cambiar tus preferencias en cualquier momento desde el enlace del pie de página."],
  ["To stop marketing emails, use the unsubscribe link in any of them.", "Pour ne plus recevoir d’e-mails marketing, utilisez le lien de désabonnement présent dans chacun d’eux.", "Um keine Marketing-E-Mails mehr zu erhalten, nutzen Sie den Abmeldelink in jeder dieser E-Mails.", "Para dejar de recibir correos de marketing, usa el enlace de cancelación que aparece en cada uno de ellos."],
  ["Terms of use", "Conditions d’utilisation", "Nutzungsbedingungen", "Condiciones de uso"],
  ["The terms of sale and of using this website.", "Les conditions de vente et d’utilisation de ce site.", "Die Verkaufsbedingungen und Bedingungen zur Nutzung dieser Website.", "Las condiciones de venta y de uso de este sitio web."],
  ["Our [terms of use](/terms) set out the terms of sale and of using this site. Nothing in them affects your legal rights as a consumer.", "Nos [conditions d’utilisation](/terms) définissent les conditions de vente et d’utilisation de ce site. Elles n’affectent en rien vos droits légaux de consommateur.", "Unsere [Nutzungsbedingungen](/terms) regeln die Verkaufsbedingungen und die Nutzung dieser Website. Sie berühren Ihre gesetzlichen Verbraucherrechte nicht.", "Nuestras [condiciones de uso](/terms) establecen las condiciones de venta y de uso de este sitio. No afectan a tus derechos legales como consumidor."],
  ["How do I contact you?", "Comment vous contacter ?", "Wie kann ich Sie kontaktieren?", "¿Cómo os contacto?"],
  ["Ways to reach us and what to include.", "Comment nous joindre et que préciser.", "Wie Sie uns erreichen und was Sie angeben sollten.", "Cómo contactarnos y qué indicar."],
  ["Use our [contact form](/help/contact) or email {mail}. Include your order number if you have one, and what you need help with, and we will get back to you as soon as we can.", "Utilisez notre [formulaire de contact](/help/contact) ou écrivez à {mail}. Indiquez votre numéro de commande si vous en avez un, ainsi que l’objet de votre demande, et nous vous répondrons dès que possible.", "Nutzen Sie unser [Kontaktformular](/help/contact) oder schreiben Sie an {mail}. Geben Sie Ihre Bestellnummer an, falls vorhanden, und worum es geht, und wir melden uns so schnell wie möglich.", "Usa nuestro [formulario de contacto](/help/contact) o escribe a {mail}. Incluye tu número de pedido si lo tienes y en qué necesitas ayuda, y te responderemos lo antes posible."],
  ["Use our [contact form](/help/contact). Include your order number if you have one, and what you need help with, and we will get back to you as soon as we can.", "Utilisez notre [formulaire de contact](/help/contact). Indiquez votre numéro de commande si vous en avez un, ainsi que l’objet de votre demande, et nous vous répondrons dès que possible.", "Nutzen Sie unser [Kontaktformular](/help/contact). Geben Sie Ihre Bestellnummer an, falls vorhanden, und worum es geht, und wir melden uns so schnell wie möglich.", "Usa nuestro [formulario de contacto](/help/contact). Incluye tu número de pedido si lo tienes y en qué necesitas ayuda, y te responderemos lo antes posible."],
  ["We are a small team and reply by email.", "Nous sommes une petite équipe et répondons par e-mail.", "Wir sind ein kleines Team und antworten per E-Mail.", "Somos un equipo pequeño y respondemos por correo."],
];
